  async capacity(): Promise<Capacity> {
    const sessions = await tmux.listSessions().catch(() => null);
    if (!sessions) return { max, inUse: 0, accepting: true };
    // TmuxUnavailable is never thrown here, so accepting: false is unreachable
    return { max, inUse: sessions.length, accepting: sessions.length < max };
  },

const CAPACITY_DEADLINE_MS = 12_000;
  async capacity(): Promise<Capacity> {
    const max = config.maxConcurrent ?? 2;
    try {
      let timer: ReturnType<typeof setTimeout> | undefined;
      const sessions = await Promise.race([
        quickTmux.jobSessions(),
        new Promise<never>((_, reject) => {
          timer = setTimeout(
            () => reject(new TmuxUnavailable("tmux list-sessions took too long")),
            CAPACITY_DEADLINE_MS,
          );
        }),
      ]).finally(() => clearTimeout(timer));
      return { max, inUse: sessions.length, accepting: true };
    } catch (err) {
      return {
        max,
        inUse: started.size,
        accepting: false,
        paused: { reason: "tmux", pools: ["heavy", "light"], detail: String(err) },
      };
    }
  },
